//! Host-facing globals. Console calls are retained as raw argument events;
//! adapters may render them without invoking extra source getters/coercions.
use crate::{Runtime,Value,JsError,JsResult,EnvId,PropertyKind};
use crate::closures::NativeFn;
fn arg(a:&[Value],i:usize)->Value{a.get(i).copied().unwrap_or(Value::Undefined)}
impl Runtime{
 pub fn install_host_builtins(&mut self)->JsResult<()>{let global=Value::Object(self.global_object);for name in["globalThis","global"]{let key=self.string(name);self.define_data(global,key,global,true,false,true)?;}let reflect=self.object();for(name,n,code)in[("ownKeys",1,reflect_keys as NativeFn),("apply",3,reflect_apply as NativeFn),("construct",2,reflect_construct as NativeFn),("get",2,reflect_get as NativeFn),("has",2,reflect_has as NativeFn),("getPrototypeOf",1,reflect_get_proto as NativeFn),("setPrototypeOf",2,reflect_set_proto as NativeFn),("deleteProperty",2,reflect_delete as NativeFn),("isExtensible",1,reflect_extensible as NativeFn),("preventExtensions",1,reflect_prevent as NativeFn),("set",3,unsupported_reflect as NativeFn),("defineProperty",3,unsupported_reflect as NativeFn)]{self.builtin(reflect,name,n,code)?;}let key=self.string("Reflect");self.define_data(global,key,reflect,true,false,true)?;let console=self.object();for(name,code)in[("log",console_log as NativeFn),("warn",console_warn as NativeFn),("error",console_error as NativeFn),("info",console_info as NativeFn),("debug",console_debug as NativeFn)]{self.builtin(console,name,0,code)?;}let key=self.string("console");self.define_data(global,key,console,true,false,true)?;for(name,n,code)in[("isNaN",1,is_nan as NativeFn),("isFinite",1,is_finite as NativeFn),("parseInt",2,parse_int as NativeFn),("parseFloat",1,parse_float as NativeFn)]{self.builtin(global,name,n,code)?;}Ok(())}
 pub fn get_with_receiver(&mut self,target:Value,key:Value,receiver:Value)->JsResult<Value>{let id=self.object_id(target)?;let key=self.to_property_key(key)?;let mut at=Some(id);while let Some(id)=at{if let Some(value)=self.typed_get(id,key)?{return Ok(value)}if let Some(desc)=self.own_descriptor(id,key)?{return match desc.kind{PropertyKind::Data{value,..}=>Ok(value),PropertyKind::Accessor{get:Some(get),..}=>self.call_value(get,receiver,&[]),PropertyKind::Accessor{get:None,..}=>Ok(Value::Undefined)}}at=self.objects[id.0].prototype;}Ok(Value::Undefined)}
}
fn reflect_keys(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{rt.object_id(arg(a,0))?;let keys=rt.own_keys(arg(a,0),false)?;Ok(rt.array(&keys.into_iter().map(Some).collect::<Vec<_>>()))}
fn list(rt:&mut Runtime,value:Value)->JsResult<Vec<Value>>{rt.object_id(value)?;let key=rt.string("length");let raw=rt.get(value,key)?;let n=rt.to_number(raw)?;if n>1_000_000.0{return Err(JsError::Unsupported("argument list exceeds resource bound".into()))}let length=if n.is_nan()||n<=0.0{0}else{n.floor()as usize};let mut args=Vec::with_capacity(length);for i in 0..length{let key=rt.string(&i.to_string());args.push(rt.get(value,key)?);}Ok(args)}
fn reflect_apply(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{if !matches!(arg(a,0),Value::Function(_)){return Err(JsError::TypeError("Reflect.apply target is not callable".into()))}let args=list(rt,arg(a,2))?;rt.call_value(arg(a,0),arg(a,1),&args)}
fn reflect_construct(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{let target=arg(a,0);let new_target=if a.len()>2{a[2]}else{target};for value in [target,new_target]{let Value::Function(id)=value else{return Err(JsError::TypeError("Reflect.construct requires constructors".into()))};if !rt.functions[id.0].constructible{return Err(JsError::TypeError("Reflect.construct requires constructors".into()))}}let args=list(rt,arg(a,1))?;rt.construct_with_new_target(target,&args,new_target)}
fn reflect_get(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{rt.get_with_receiver(arg(a,0),arg(a,1),if a.len()>2{a[2]}else{arg(a,0)})}
fn reflect_has(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{Ok(Value::Bool(rt.has_property(arg(a,0),arg(a,1))?))}
fn reflect_get_proto(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{let id=rt.object_id(arg(a,0))?;Ok(rt.objects[id.0].prototype.map(|p|rt.value_for_object(p)).unwrap_or(Value::Null))}
fn reflect_set_proto(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{rt.object_id(arg(a,0))?;if !matches!(arg(a,1),Value::Null|Value::Object(_)|Value::Function(_)){return Err(JsError::TypeError("prototype must be object or null".into()))}match rt.set_prototype(arg(a,0),arg(a,1)){Ok(_)=>Ok(Value::Bool(true)),Err(JsError::TypeError(_))=>Ok(Value::Bool(false)),Err(e)=>Err(e)}}
fn reflect_delete(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{rt.object_id(arg(a,0))?;Ok(Value::Bool(rt.delete(arg(a,0),arg(a,1),false)?))}
fn reflect_extensible(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{let id=rt.object_id(arg(a,0))?;Ok(Value::Bool(rt.objects[id.0].extensible))}
fn reflect_prevent(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{let id=rt.object_id(arg(a,0))?;rt.objects[id.0].extensible=false;Ok(Value::Bool(true))}
fn unsupported_reflect(_: &mut Runtime,_:Value,_:&[Value],_:EnvId)->JsResult<Value>{Err(JsError::Unsupported("Reflect operation requires full boolean descriptor-result semantics".into()))}
macro_rules! console{($name:ident,$level:literal)=>{fn $name(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{rt.console_output.push(($level,a.to_vec()));Ok(Value::Undefined)}}}
console!(console_log,"log");console!(console_warn,"warn");console!(console_error,"error");console!(console_info,"info");console!(console_debug,"debug");
fn is_nan(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{Ok(Value::Bool(rt.to_number(arg(a,0))?.is_nan()))}
fn is_finite(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{Ok(Value::Bool(rt.to_number(arg(a,0))?.is_finite()))}
fn whitespace(c:u16)->bool{matches!(c,0x0009..=0x000d|0x0020|0x00a0|0x1680|0x2000..=0x200a|0x2028|0x2029|0x202f|0x205f|0x3000|0xfeff)}
fn parse_int(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{let string=rt.to_string(arg(a,0))?;let units=rt.string_units(string);let mut start=0;while start<units.len()&&whitespace(units[start]){start+=1;}let negative=units.get(start)==Some(&45);if matches!(units.get(start),Some(43|45)){start+=1;}let mut radix=rt.to_int32(arg(a,1))?;let units=rt.string_units(string);let strip=radix==0||radix==16;if radix!=0&&!(2..=36).contains(&radix){return Ok(Value::Number(crate::value::CONVERSION_NAN))}if radix==0{radix=10}if strip&&units.get(start)==Some(&48)&&matches!(units.get(start+1),Some(88|120)){start+=2;radix=16;}let begin=start;let mut integer=0u128;let mut overflow=false;while let Some(c)=units.get(start){let digit=match *c{48..=57=>*c-48,65..=90=>*c-65+10,97..=122=>*c-97+10,_=>break};if digit>=radix as u16{break}if let Some(n)=integer.checked_mul(radix as u128).and_then(|n|n.checked_add(digit as u128)){integer=n}else{overflow=true}start+=1;}if start==begin{return Ok(Value::Number(crate::value::CONVERSION_NAN))}let number=if radix==10{{let digits=&units[begin..start];if digits.len()<=64{let mut ascii=[0u8;64];for (out,unit) in ascii.iter_mut().zip(digits){*out=*unit as u8;}std::str::from_utf8(&ascii[..digits.len()]).expect("decimal scanner admits only ASCII digits").parse::<f64>().unwrap_or(f64::INFINITY)}else{String::from_utf16_lossy(digits).parse::<f64>().unwrap_or(f64::INFINITY)}}}else{if overflow||integer>9_007_199_254_740_991{return Err(JsError::Unsupported("large nondecimal parseInt rounding is not yet implemented".into()))}integer as f64};Ok(Value::Number(if negative{-number}else{number}))}
fn parse_float(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{let string=rt.to_string(arg(a,0))?;let units=rt.string_units(string);let mut start=0;while start<units.len()&&whitespace(units[start]){start+=1;}let begin=start;if matches!(units.get(start),Some(43|45)){start+=1;}let infinity="Infinity".encode_utf16().collect::<Vec<_>>();if units.get(start..start+infinity.len())==Some(&infinity[..]){return Ok(Value::Number(if units.get(begin)==Some(&45){f64::NEG_INFINITY}else{f64::INFINITY}))}let digits_start=start;while units.get(start).is_some_and(|c|(48..=57).contains(c)){start+=1;}let mut digits=start-digits_start;if units.get(start)==Some(&46){start+=1;let p=start;while units.get(start).is_some_and(|c|(48..=57).contains(c)){start+=1;}digits+=start-p;}if digits==0{return Ok(Value::Number(crate::value::CONVERSION_NAN))}if matches!(units.get(start),Some(69|101)){let exponent=start;start+=1;if matches!(units.get(start),Some(43|45)){start+=1;}let p=start;while units.get(start).is_some_and(|c|(48..=57).contains(c)){start+=1;}if start==p{start=exponent;}}let text=String::from_utf16_lossy(&units[begin..start]);Ok(Value::Number(text.parse::<f64>().unwrap_or(crate::value::CONVERSION_NAN)))}
